  {
    "prompt": "In a SUMIFS condition, what does \">=100000\" mean?",
    "options": ["100,000 or more", "Less than 100,000", "Exactly 100,000", "Not 100,000"],
    "answer": 0,
    "explanation": ">= means greater than or equal to."
  }
]
```
